const aliases=new Map([['giao diện','ui design'],['giao dien','ui design'],['bảo mật','security'],['bao mat','security'],['định tuyến','routing'],['dinh tuyen','routing'],['kiểm thử','testing'],['kiem thu','testing'],['kế hoạch','planning'],['ke hoach','planning']]);
export function normalizeQuery(value){let text=String(value??'').toLowerCase().normalize('NFKC');for(const [from,to] of aliases)text=text.replaceAll(from,to);return text.replace(/[^\p{L}\p{N}]+/gu,' ').trim();}
export function tokens(value){return new Set(normalizeQuery(value).split(/\s+/).filter(Boolean));}
function tokenMatch(a,b){if(a===b)return true;if(Math.min(a.length,b.length)<5)return false;let common=0;while(common<Math.min(a.length,b.length)&&a[common]===b[common])common++;return common>=Math.min(6,Math.min(a.length,b.length)-1);}
function overlap(queryTokens,values){const hay=tokens(values.join(' '));let hits=0;for(const token of queryTokens)if([...hay].some((candidate)=>tokenMatch(token,candidate)))hits++;return queryTokens.size?hits/queryTokens.size:0;}
function antiTriggerMatch(query,antiTriggers){const q=normalizeQuery(query);const qTokens=tokens(query);for(const anti of antiTriggers??[]){const normalized=normalizeQuery(anti);const a=tokens(normalized);let hits=0;for(const token of a)if(qTokens.has(token))hits++;const coverage=a.size?hits/a.size:0;const sufficientlySpecific=a.size<=2?hits===a.size:hits>=3&&coverage>=.67;if(q.includes(normalized)||sufficientlySpecific)return anti;}return null;}
export function retrieveOutcomes(graph,intent,{limit=12}={}){const queryTokens=tokens(intent.query);const domains=new Set(intent.domains??[]);const targets=new Set(intent.targetOutcomeIds??[]);return graph.outcomes.map((outcome)=>{let score=0;const reasons=[];if(targets.has(outcome.outcomeId)){score+=100;reasons.push('explicit-target');}if(domains.has(outcome.domain)){score+=25;reasons.push(`domain:${outcome.domain}`);}const lexical=overlap(queryTokens,[outcome.title,outcome.domain,...(outcome.produces??[]),...(outcome.evidence??[])]);score+=lexical*45;if(lexical)reasons.push(`lexical:${lexical.toFixed(2)}`);return{outcome,score,reasons};}).filter((item)=>item.score>0).sort((a,b)=>b.score-a.score||a.outcome.outcomeId.localeCompare(b.outcome.outcomeId)).slice(0,limit);}
export function retrieveTechniques(graph,outcomeCandidates,intent,{limit=24}={}){const outcomes=new Map(outcomeCandidates.map((item)=>[item.outcome.outcomeId,item]));const queryTokens=tokens(intent.query);const requestedDomains=new Set(intent.domains??[]);const result=[];for(const technique of graph.techniques){const allMappings=graph.relations.filter((edge)=>edge.type==='satisfies'&&edge.from===technique.techniqueId);const mapped=allMappings.filter((edge)=>outcomes.has(edge.to));const trigger=overlap(queryTokens,technique.triggers??[]);const domainMatch=(technique.domains??[]).includes('all')||(technique.domains??[]).some((domain)=>requestedDomains.has(domain));const directEligible=trigger>=0.16&&(domainMatch||requestedDomains.size===0);const anti=antiTriggerMatch(intent.query,technique.antiTriggers);if(anti&&(mapped.length||directEligible)){result.push({technique,score:-Infinity,reasons:[`anti-trigger:${anti}`],mappedOutcomes:allMappings.map((edge)=>edge.to),excluded:true});continue;}if(!mapped.length&&!directEligible)continue;const mappedScore=mapped.length?Math.max(...mapped.map((edge)=>(outcomes.get(edge.to)?.score??0)+(edge.fitScore??0)/5)):Math.max(0,...allMappings.map((edge)=>(edge.fitScore??0)/5));const directBonus=directEligible?20:0;const domainBonus=domainMatch?8:0;result.push({technique,score:mappedScore+trigger*60+directBonus+domainBonus,reasons:[`trigger:${trigger.toFixed(2)}`,...(directEligible?['direct-technique-retrieval']:[]),...(domainMatch?['technique-domain-fit']:[]),...allMappings.map((edge)=>`outcome:${edge.to}`)],mappedOutcomes:allMappings.map((edge)=>edge.to),excluded:false});}return result.sort((a,b)=>b.score-a.score||a.technique.techniqueId.localeCompare(b.technique.techniqueId)).slice(0,limit);}
